def zip_dicts(*dicts):
    """Yields tuples like (key, (val1, val2, ...))
       for each common key in all given dicts."""
    if len(dicts) < 2:
        raise TypeError('zip_dicts expects at least two arguments')
    keys = set.union(*map(set, dicts))
    for key in keys:
        yield key, tuple(d.get(key) for d in dicts)

